<?php
// Gemensam panel "Tjänster och kontroller" för server-, host- och nätverkssidor
function parse_check($cat){ $src=$_POST['source']??''; $kind=$t=$p='';
 if($src==='zabbix'){ $kind=$_POST['z_kind']??''; $t=trim($_POST['z_target']??''); $p=$kind==='docker_containers'?($GLOBALS['old_param']??''):trim($_POST['z_param']??''); }
 elseif($src==='snmp'){ $kind='all'; $p=snmp_param_build($_POST['s_ver']??'2',$_POST,$GLOBALS['old_param']??''); $t=''; }
 elseif($src==='tcp'){ $kind=$_POST['t_kind']??''; $p=preg_replace('/\D/','',$_POST['t_port']??''); }
 elseif($src==='url'){ $kind=$_POST['u_kind']??''; $t=trim($_POST['u_target']??''); $p=trim($_POST['u_param']??''); }
 elseif($src==='docker'){ $kind='containers'; $t=trim($_POST['d_target']??''); $p=$GLOBALS['old_param']??''; }
 elseif($src==='ha'){ $kind='api'; $t=trim($_POST['h_target']??''); $tk=trim($_POST['h_token']??''); $ot=($tk!==''&&$tk!=='********')?secret_enc($tk):ha_conn($GLOBALS['old_param']??'')['tok']; if($ot==='') return null; $p=ha_pack($ot,(array)($_POST['ha_o']??[])); }
 elseif($src==='pbs'){ $kind='all'; $t=''; $p=preg_replace('/\D/','',$_POST['p_param']??''); }
 $e=$cat[$src][$kind]??null; if(!$e||($e[3]&&$t==='')||($kind==='contains'&&$p==='')||($kind==='custom'&&$p==='')) return null;
 $iv=iv_post();
 $mu=1;$mm=0; if($src==='tcp'||$src==='url'){ $mu=isset($_POST['mon_up'])?1:0; $mm=isset($_POST['mon_ms'])?1:0; if(!$mu&&!$mm) $mu=1; }
 return [$src,$kind,$t,$p,trim($_POST['label']??'')?:($src==='snmp'?'SNMP':($e[3]&&$t!==''?$t:$e[0])),$iv,$mu,$mm,($ic=trim($_POST['icon']??''))!==''&&icon_spec_ok($ic)?$ic:'']; }
function checks_post($id){ $a=$_POST['a']??''; if(!in_array($a,['add_check','edit_check','test_check','toggle_disk','toggle_enabled','toggle_hide','del_check','del_tn','test_tn','toggle_tn','dk_hide'],true)) return false; $cat=catalog(true); $cid=(int)($_POST['cid']??0); $self=basename($_SERVER['SCRIPT_NAME']); $id=(int)$id;
 $bad=t('Kunde inte spara – fyll i alla obligatoriska fält.','Could not save – fill in all required fields.');
 if($a==='dk_hide'){ $q=db()->prepare('SELECT param FROM server_checks WHERE id=? AND server_id=?'); $q->execute([$cid,$id]); $pr=$q->fetchColumn(); if($pr!==false){ $n=trim((string)($_POST['n']??'')); $l=array_values(array_filter(array_map('trim',explode(',',(string)$pr)))); $k=array_search($n,$l,true); if($k===false&&$n!=='') $l[]=$n; elseif($k!==false) unset($l[$k]); db()->prepare('UPDATE server_checks SET param=?,last_check=NULL WHERE id=? AND server_id=?')->execute([implode(',',$l),$cid,$id]); } header('Location: '.$self."?id=$id");exit; }
 if($a==='add_check'&&($_POST['source']??'')==='tnapi'){ $_SESSION['flash']=tn_save_conn($id)?t('TrueNAS API sparad – hämtas vid nästa avläsning.','TrueNAS API saved – fetched on the next poll.'):t('Fyll i API-nyckel.','Enter an API key.'); header('Location: '.$self."?id=$id");exit; }
 if($a==='test_tn'){ $q=db()->prepare('SELECT * FROM servers WHERE id=?'); $q->execute([$id]); $sv=$q->fetch(); $cn=json_decode((string)($sv['nw_conn']??''),true)?:[]; if($sv&&tn_on($cn)){ $r=tn_probe($sv['host'],$cn); if($r['ok']){ $bad2=count(array_filter($r['health'],fn($x)=>$x['st']!=='ok')); $_SESSION['flash']='✔ TrueNAS API: '.count($r['pools']).' '.t('pooler','pools').', '.count($r['smart']).' '.t('diskar','disks').' ('.t('SMART-värden för','SMART values for').' '.(int)$r['attr'].'), '.($bad2?', '.$bad2.' '.t('avvikande','not OK'):', OK'); try{ poll_network($sv); }catch(Throwable $e){} } else $_SESSION['flash']='✖ TrueNAS API: '.$r['error']; } header('Location: '.$self."?id=$id");exit; }
 if($a==='toggle_tn'){ $q=db()->prepare('SELECT nw_conn FROM servers WHERE id=?'); $q->execute([$id]); $cn=json_decode((string)$q->fetchColumn(),true)?:[]; if(!empty($cn['tn'])){ if(empty($cn['tn']['off'])) $cn['tn']['off']=1; else unset($cn['tn']['off']); db()->prepare('UPDATE servers SET nw_conn=?,nw_poll=NULL WHERE id=?')->execute([json_encode($cn),$id]); } header('Location: '.$self."?id=$id");exit; }
 if($a==='del_tn'){ tn_del_conn($id); $_SESSION['flash']=t('TrueNAS API borttagen.','TrueNAS API removed.'); header('Location: '.$self."?id=$id");exit; }
 if($a==='add_check'){ if($x=parse_check($cat)){ if($x[0]==='pbs') pbs_save_conn($id); db()->prepare('INSERT INTO server_checks(server_id,source,kind,target,param,label,interval_sec,mon_up,mon_ms,icon) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute(array_merge([$id],$x)); } else $_SESSION['flash']=$bad; }
 if($a==='edit_check'){ $oq=db()->prepare('SELECT param FROM server_checks WHERE id=? AND server_id=?'); $oq->execute([$cid,$id]); $GLOBALS['old_param']=(string)$oq->fetchColumn(); if($x=parse_check($cat)){ $o=db()->prepare('SELECT source,target FROM server_checks WHERE id=? AND server_id=?'); $o->execute([$cid,$id]); $o=$o->fetch(); if($x[0]==='pbs') pbs_save_conn($id); if(in_array($x[0],['snmp','pbs'],true)) $x[2]=($o&&$o['source']===$x[0])?$o['target']:''; db()->prepare('UPDATE server_checks SET source=?,kind=?,target=?,param=?,label=?,interval_sec=?,mon_up=?,mon_ms=?,icon=?,last_status=NULL,last_detail=NULL,last_value=NULL,last_data=NULL,last_check=NULL WHERE id=? AND server_id=?')->execute(array_merge($x,[$cid,$id])); $_SESSION['flash']=t('Ändringarna sparades.','Changes saved.'); } else { $_SESSION['flash']=$bad; header('Location: '.$self."?id=$id&edit=$cid");exit; } }
 if($a==='test_check'||$a==='toggle_disk'){ $q=db()->prepare('SELECT c.*,s.host FROM server_checks c JOIN servers s ON s.id=c.server_id WHERE c.id=? AND c.server_id=?'); $q->execute([$cid,$id]); $c=$q->fetch();
  if($c&&$a==='test_check'){ $r=exec_check($c); store_result($c,$r); $_SESSION['flash']=($r[0]?'✔ ':'✖ ').$c['label'].': '.$r[1]; }
  if($c&&$a==='toggle_disk'){ $l=array_values(array_filter(array_map('trim',explode(',',$c['target'])),'strlen')); $n=trim($_POST['name']); $k=array_search(strtolower($n),array_map('strtolower',$l),true);
   if($k===false){ $l[]=$n; $_SESSION['flash']=strpos($n,'job:')===0?t('Jobbet är nu dolt på dashboard.','The job is now hidden on the dashboard.'):t("Disken $n är nu dold på dashboard.","Disk $n is now hidden on the dashboard."); } else { array_splice($l,$k,1); $_SESSION['flash']=strpos($n,'job:')===0?t('Jobbet visas på dashboard igen.','The job is shown on the dashboard again.'):t("Disken $n visas på dashboard igen.","Disk $n is shown on the dashboard again."); }
   db()->prepare('UPDATE server_checks SET target=? WHERE id=?')->execute([implode(',',$l),$cid]); } }
 if($a==='toggle_enabled') db()->prepare('UPDATE server_checks SET enabled=1-enabled,last_check=IF(enabled=1,NULL,last_check) WHERE id=? AND server_id=?')->execute([$cid,$id]);
 if($a==='toggle_hide') db()->prepare('UPDATE server_checks SET hidden=1-hidden WHERE id=? AND server_id=?')->execute([$cid,$id]);
 if($a==='del_check'){ purge_targets([],[$cid]); } if($a==='del_check') db()->prepare('DELETE FROM server_checks WHERE id=? AND server_id=?')->execute([$cid,$id]);
 header('Location: '.$self."?id=$id");exit; }
function checks_panel($srv){ $id=(int)$srv['id']; $cat=catalog(true); $self=basename($_SERVER['SCRIPT_NAME']);
$ed=null; if(isset($_GET['edit'])&&is_admin()){ $q=db()->prepare('SELECT * FROM server_checks WHERE id=? AND server_id=?'); $q->execute([(int)$_GET['edit'],$id]); $ed=$q->fetch()?:null; }
$cs=db()->query("SELECT * FROM server_checks WHERE server_id=$id ORDER BY ".chk_ord())->fetchAll();
$up=[]; foreach(db()->query("SELECT check_id,SUM(IF(hr>=NOW()-INTERVAL 1 DAY,up,0)) u1,SUM(IF(hr>=NOW()-INTERVAL 1 DAY,total,0)) t1,SUM(IF(hr>=NOW()-INTERVAL 7 DAY,up,0)) u7,SUM(IF(hr>=NOW()-INTERVAL 7 DAY,total,0)) t7,SUM(IF(hr>=NOW()-INTERVAL 30 DAY,up,0)) u30,SUM(IF(hr>=NOW()-INTERVAL 30 DAY,total,0)) t30,SUM(up) ua,SUM(total) ta FROM check_hist WHERE check_id IN (SELECT id FROM server_checks WHERE server_id=$id) GROUP BY check_id") as $r) $up[$r['check_id']]=$r;
$istn=($srv['nw_type']??'')==='truenas'; $tnc=(json_decode((string)($srv['nw_conn']??''),true)?:[])['tn']??[]; $sel=$ed['source']??(isset($_GET['edit_api'])&&$istn?'tnapi':'zabbix'); $lab=$ed?h($ed['label']):''; $sp=snmp_param_parse($ed&&$ed['source']==='snmp'?$ed['param']:'');
$pc=pbs_conn($id); $sinf=json_decode((string)($srv['info']??''),true)?:[]; $ispbs=(($sinf['hv']['type']??'')==='pbs')||stripos((string)($srv['os_info']??''),'Proxmox Backup')!==false||(bool)array_filter($cs,fn($x)=>$x['source']==='pbs');
$defs=['tcp'=>(int)setting('int_tcp',30),'url'=>(int)setting('int_url',60),'snmp'=>(int)setting('int_snmp',60),'zabbix'=>(int)setting('int_zabbix',60),'docker'=>(int)setting('int_zabbix',60),'ha'=>(int)setting('int_zabbix',60)];
?>
